dslRule:
/*!id: add.classpath_entry_jrt_system_check*/
/*!description: Extends a boolean condition (e.g., in an 'if' statement or 'Assert.isTrue' call) that checks if a classpath entry kind is not 'CPE_LIBRARY' or 'CPE_VARIABLE' to also include 'CPE_JRT_SYSTEM'. This is relevant for Java 9+ projects that use JRT system libraries.*/
/*!severity: HINT*/
org.eclipse.jdt.core.IClasspathEntry $kind != org.eclipse.jdt.core.IClasspathEntry.CPE_LIBRARY && $kind != org.eclipse.jdt.core.IClasspathEntry.CPE_VARIABLE :: sourceVersionGE(9)
=>
$kind != org.eclipse.jdt.core.IClasspathEntry.CPE_LIBRARY && $kind != org.eclipse.jdt.core.IClasspathEntry.CPE_VARIABLE && $kind != org.eclipse.jdt.core.IClasspathEntry.CPE_JRT_SYSTEM
;;

beforeExample:
package test;

import org.eclipse.jdt.core.IClasspathEntry;

public class TestClass {
    public void checkEntry(int entryKind) {
        if (entryKind != IClasspathEntry.CPE_LIBRARY && entryKind != IClasspathEntry.CPE_VARIABLE) {
            System.out.println("Invalid entry kind: " + entryKind);
        }
    }
}

afterExample:
package test;

import org.eclipse.jdt.core.IClasspathEntry;

public class TestClass {
    public void checkEntry(int entryKind) {
        if (entryKind != IClasspathEntry.CPE_LIBRARY && entryKind != IClasspathEntry.CPE_VARIABLE && entryKind != IClasspathEntry.CPE_JRT_SYSTEM) {
            System.out.println("Invalid entry kind: " + entryKind);
        }
    }
}

negativeExample:
package test;

import org.eclipse.jdt.core.IClasspathEntry;

public class NegativeTestClass {
    public void checkEntry(int entryKind) {
        // This should not be modified because the pattern doesn't match
        if (entryKind != IClasspathEntry.CPE_SOURCE && entryKind != IClasspathEntry.CPE_CONTAINER) {
            System.out.println("Another invalid entry kind: " + entryKind);
        }
        // This is already correct, should not be re-modified by the rule
        if (entryKind != IClasspathEntry.CPE_LIBRARY && entryKind != IClasspathEntry.CPE_VARIABLE && entryKind != IClasspathEntry.CPE_JRT_SYSTEM) {
             System.out.println("Already updated condition: " + entryKind);
        }
    }
}
